#ifndef __NEXTHOP_BUCKET_H__
#define __NEXTHOP_BUCKET_H__

#include "../scamptrie_base.h"

#include <vector>

// allocate memory for nexthop info
class NexthopBucket {
    static const uint32_t NEXTHOP_BUCKET_SIZE = (1e6) - 1;
public:
    NexthopBucket();
    ~NexthopBucket();

    /// Retrieves nexthop at specified position
    nexthop_t get_nh(uint32_t ptr, uint32_t pos) const;
    /// Retrieves bmp at specified position
    uint32_t get_bmp_idx(uint32_t ptr, uint32_t pos) const;
    /// Allocates new nexthop segment
    /// @return Pointer to allocated segment
    uint32_t alloc();
    /// Free the segment
    void free(uint32_t ptr);
    /// Gets number of nexthops in segment
    /// @return Nexthop count
    uint32_t get_size(uint32_t ptr) const;
    /// Inserts nexthop at specified position
    /// @param ptr Segment pointer (may change on reallocation)
    /// @param pos Position in segment
    /// @param nh Nexthop to insert
    /// @param bmp BMP (Index of BMPManager)
    void insert(uint32_t &ptr, uint32_t pos, nexthop_t nh, uint32_t bmp = 0);

private:
    std::vector<nexthop_t> buckets[NEXTHOP_BUCKET_SIZE];
    std::vector<uint32_t> bmp_buckets[NEXTHOP_BUCKET_SIZE];
    uint32_t size;
    uint32_t reallocated_ptrs[NEXTHOP_BUCKET_SIZE];
    uint32_t reallocated_size;
};

#endif // __NEXTHOP_BUCKET_H__
#ifndef __NEXTHOP_BITMAP_BUCKET_H__
#define __NEXTHOP_BITMAP_BUCKET_H__

#include "../scamptrie_base.h"

class MemInit;  // Forward declaration

class NexthopBitmapBucket {
    friend class MemInit;
    static const int BUCKET_SIZE = (1 << 16) - 1;
public:
    NexthopBitmapBucket() {size = 0;};
    ~NexthopBitmapBucket() = default;

    void clear() {size = 0;}

    uint16_t get_size() const { return size; }
    // get index of bitmap, if not exist, insert it
    uint16_t get_bitmap_index(uint64_t prefix) {
        for (uint16_t i = 0; i < size; ++i)
            if (buckets[i] == prefix)
                return i;
        if (size < BUCKET_SIZE) {
            buckets[size] = prefix;
            return size++;
        }
        msg_error("NexthopBitmapBucket::get_bitmap_index: Bucket Full");
        return -1;
    }

    uint64_t get_bitmap(uint16_t index) const {
        if (index < size) return buckets[index];
        msg_error("NexthopBitmapBucket::get_bitmap: Index out of range");
        return UINT64_MAX;
    }
private:
    uint64_t buckets[BUCKET_SIZE];
    uint16_t size;
};

#endif // __NEXTHOP_BITMAP_BUCKET_H__
#ifndef __SCAMPTRIE_HASH_H__
#define __SCAMPTRIE_HASH_H__

#include <functional>
#include <cstdint>

#define HASH_TABLE_SIZE (1024 * 4)

class MemInit;  // Forward declaration

class ScampTrieHash {
    friend class MemInit;
public:
    ScampTrieHash();
    ~ScampTrieHash() = default;

    // get the hash value for key
    bool get64_12(uint64_t key, uint16_t& hash_val);
    // alloc a new entry for key
    bool alloc64_12(uint64_t key);
    bool get_key_by_idx(uint32_t idx, uint64_t& key);


    uint32_t get_used_bucket_count() const;

    bool has_any_bucket() const;
private:
    static uint16_t compute_hash_index(uint64_t ip);
    uint64_t bucket_keys[HASH_TABLE_SIZE];
    bool bucket_occupied[HASH_TABLE_SIZE];
    std::hash<uint64_t> hash_fn;
};

#endif // __SCAMPTRIE_HASH_H__
#include "scamptrie_hash.h"

#include <cstring>
#include <cstdio>

ScampTrieHash::ScampTrieHash() {
    memset(bucket_occupied, 0, sizeof(bucket_occupied));
}





// assign hash1_index = mix2[11:0] ^ mix2[23:12] ^ mix2[35:24] ^ mix2[47:36] ^ mix2[59:48];
uint16_t ScampTrieHash::compute_hash_index(uint64_t ip) {

    uint64_t rotated_16 = (ip << 16) | (ip >> 48);
    uint64_t mix1 = ip ^ rotated_16;


    uint64_t rotated_32 = (mix1 << 32) | (mix1 >> 32);
    uint64_t mix2 = mix1 ^ rotated_32;

    // hash1_index = mix2[11:0] ^ mix2[23:12] ^ mix2[35:24] ^ mix2[47:36] ^ mix2[59:48]
    uint64_t hash_index = (mix2 & 0xFFF) ^                    // mix2[11:0]
                          ((mix2 >> 12) & 0xFFF) ^            // mix2[23:12]
                          ((mix2 >> 24) & 0xFFF) ^            // mix2[35:24]
                          ((mix2 >> 36) & 0xFFF) ^            // mix2[47:36]
                          ((mix2 >> 48) & 0xFFF);             // mix2[59:48]

    // printf("Hash: %016llX -> %d\n", ip, (uint16_t)(hash_index % HASH_TABLE_SIZE));
    return hash_index % HASH_TABLE_SIZE;
}

bool ScampTrieHash::get64_12(uint64_t key, uint16_t& hash_val) {
    // size_t idx = compute_hash_index(key);
    size_t idx = hash_fn(key) % HASH_TABLE_SIZE;
    size_t start_idx = idx;
    while (bucket_occupied[idx]) {
        if (bucket_keys[idx] == key) {
            hash_val = idx;
            return true;
        }
        idx = (idx + 1) % HASH_TABLE_SIZE;
        if (idx == start_idx)
            return false;
    }
    return false;
}

bool ScampTrieHash::alloc64_12(uint64_t key) {
    // size_t idx = compute_hash_index(key);
    size_t idx = hash_fn(key) % HASH_TABLE_SIZE;
    size_t start_idx = idx;
    while (bucket_occupied[idx]) {
        if (bucket_keys[idx] == key) {
            return true;
        }
        // printf("############# HASH INTERRUPTED, key: %016llX\n", key);
        idx = (idx + 1) % HASH_TABLE_SIZE;
        if (idx == start_idx) {
            printf("Hash::alloc64_12 failed\n");
            return false;
        }
    }
    bucket_keys[idx] = key;
    bucket_occupied[idx] = true;
    return true;
}

bool ScampTrieHash::get_key_by_idx(uint32_t idx, uint64_t& key) {
    if (idx >= HASH_TABLE_SIZE)
        return false;
    if (!bucket_occupied[idx])
        return false;
    key = bucket_keys[idx];
    return true;
}

uint32_t ScampTrieHash::get_used_bucket_count() const {
    uint32_t cnt = 0;
    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        if (bucket_occupied[i])
            ++cnt;
    }
    return cnt;
}

bool ScampTrieHash::has_any_bucket() const {
    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        if (bucket_occupied[i])
            return true;
    }
    return false;
}
#include "nexthop_bucket.h"
#include <cstdio>
#include <cstdlib>

NexthopBucket::NexthopBucket() {
    size = 0;
}

NexthopBucket::~NexthopBucket() {
    for (int i = 0; i < size; ++i)
        buckets[i].clear();
    for (int i = 0; i < NEXTHOP_BUCKET_SIZE; ++i)
        bmp_buckets[i].clear();
    size = 0;
    reallocated_size = 0;
}

nexthop_t NexthopBucket::get_nh(uint32_t ptr, uint32_t pos) const {
    if (ptr >= size) msg_error("NexthopBucket::get: Index out of range");
    if (pos >= buckets[ptr].size()) msg_error("NexthopBucket::get: Position out of range");
    return buckets[ptr][pos];
}

uint32_t NexthopBucket::get_bmp_idx(uint32_t ptr, uint32_t pos) const {
    if (ptr >= size) msg_error("NexthopBucket::get_bmp_idx: Index out of range");
    if (pos >= bmp_buckets[ptr].size()) msg_error("NexthopBucket::get_bmp_idx: Position out of range");
    return bmp_buckets[ptr][pos];
}

uint32_t NexthopBucket::alloc() {
    if (size >= NEXTHOP_BUCKET_SIZE) {
        msg_error("NexthopBucket::alloc: Nexthop bucket full!");
        return UINT32_MAX;
    }
    buckets[size].clear();
    bmp_buckets[size].clear();
    uint32_t ptr;
    if (reallocated_size > 0) {
        ptr = reallocated_ptrs[reallocated_size - 1];
        reallocated_size--;
    } else {
        ptr = size++;
    }
    return ptr;
}

void NexthopBucket::free(uint32_t ptr) {
    if (reallocated_size >= NEXTHOP_BUCKET_SIZE) msg_error("NexthopBucket::free: Reallocated size out of range");
    reallocated_ptrs[reallocated_size++] = ptr;
    buckets[ptr].clear();
    bmp_buckets[ptr].clear();
}

uint32_t NexthopBucket::get_size(uint32_t ptr) const {
    if (ptr >= size) msg_error("NexthopBucket::get_size: Index out of range");
    return buckets[ptr].size();
}

void NexthopBucket::insert(uint32_t &ptr, uint32_t pos, nexthop_t nh, uint32_t bmp) {
    if (ptr >= size) {
        printf("NexthopBucket::insert: Index out of range, ptr: %d, size: %d\n", ptr, size);
        exit(1);
    }
    if (pos > buckets[ptr].size()) msg_error("NexthopBucket::insert: Position out of range");
    buckets[ptr].insert(buckets[ptr].begin() + pos, nh);
    bmp_buckets[ptr].insert(bmp_buckets[ptr].begin() + pos, bmp);
    ptr = ptr; // for the std::vector implementation -> always keep the same segment
}
